from mcp.server.fastmcp import FastMCP

mcp = FastMCP("Enterprise-PostgreSQL-Service")

@mcp.tool()
def execute_readonly_sql(query: str) -> str:
    """Executes a read-only SQL SELECT query against production read-replica."""
    if any(keyword in query.upper() for keyword in ["DROP", "DELETE", "INSERT", "UPDATE"]):
        raise ValueError("Write operations strictly prohibited via MCP!")
    return db_pool.query_as_json(query)

if __name__ == "__main__":
    mcp.run()
